SELECT NVL((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PO.WAREHOUSE_CODE),'-') AS WAREHOUSE_CODE_TEXT, NVL(A.BUYER_NAME, '-') AS BUYER_NAME, NVL(A.BUYER,' ') AS BUYER, TO_CHAR(TO_DATE(A.ADD_DATE,'YYYYMMDD'),'YY-MM-DD') AS ISSUE_DATE, NVL(PO.PO_NO,'-') AS PO_NO, NVL(PO.PO_SEQ,'-') AS PO_SEQ, NVL(PO.BUYER_ITEM_NO,'-') AS BUYER_ITEM_NO, NVL(PO.DESCRIPTION,'-') AS DESCRIPTION, NVL(PO.SPECIFICATION,'-') AS SPECIFICATION, NVL(PO.AGENT_PRICE,'-') AS AGENT_PRICE, NVL(PO.UNIT_MEASURE,'-') AS UNIT_MEASURE, NVL(PO.GR_QTY,'-') AS GR_QTY, NVL(PO.AGENT_PRICE * PO.GR_QTY,'-') AS AGENT_ITEM_AMT, A.PAY_AMT AS LOGIS_AMT, A.ADD_USER_NAME || '(' || (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = A.ADD_USER_ID) || ')' AS KEP_USER_NAME, NULL AS KEP_USER_PHONE, '수기' AS LOGIS_TYPE FROM PAY_REG_MNG A, ICOMPODT PO WHERE A.STATUS IN ('C','R') AND A.BUYER = PO.BUYER(+) AND A.PO_NO = PO.PO_NO(+) AND A.PO_SEQ = PO.PO_SEQ(+) AND A.AGENT = #{st_com_code} AND A.PAY_REG_TYPE = 'C' AND A.PAY_REG_STATUS = 'C' AND A.BILL_CLOSE_MONTH = #{st_from_date}
AND A.BUYER_NAME LIKE '%' || #{st_buyer_name} || '%'
AND (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PO.WAREHOUSE_CODE) LIKE '%' || #{st_warehouse_name} || '%'
AND A.PAY_REG_TYPE = 'XX'
AND PO.PO_NO = #{st_po_no}
) X

